      plugins: [hl([4], [15], XH), { id: 'qz', afterDraw: function (ch) { var a = ch.chartArea, ctx = ch.ctx; ctx.save(); ctx.fillStyle = XH; ctx.font = '600 11px ' + tok('--mono'); ctx.textAlign = 'right'; ctx.fillText('bill ≥ 4% and ≥ 15 deaths/100k', a.right - 6, a.top + 14); ctx.restore(); } }, labels(narrow ? ['CHN', 'IND', 'ZAF', 'POL', 'MKD', 'LBN', 'GRC'] : ['IND', 'CHN', 'ZAF', 'POL', 'GRC', 'MKD', 'BGR', 'TUR', 'LBN', 'JPN', 'UKR'])],
