      options: { indexAxis: 'y', plugins: { legend: { position: 'bottom' }, tooltip: { callbacks: { afterBody: function (it) { var o = EX[it[0].dataIndex]; return 'fuel imports ' + nn(o.fib, 1, '%') + ' · ' + nn(o.pop, 1, ' m people') + ' · ' + INCN[o.inc]; } } } }, scales: { x: Object.assign(axis({ title: '% of GDP' }), { min: 0, max: 80 }), y: Object.assign(axis({ grid: false }), { ticks: Object.assign({ autoSkip: false }, tick, { font: { size: 10.5 } }) }) } },
