    var INV = [['Clean energy, total', 2200, XG], ['Power supply & grids', 1600, EL], ['Renewable power', 665, ES], ['… of which solar', 365, alpha(ES, 0.6)], ['Fossil fuels, total', 1200, EF], ['Oil (below)', 500, EO], ['Natural gas', 330, alpha(EF, 0.75)], ['Coal', 180, alpha(INK, 0.55)]];
