    if (sel) { sel.innerHTML = SA.map(function (c) { return '<option value="' + c.iso + '">' + shortName(c.name) + '</option>'; }).join(''); sel.value = 'MAR'; sel.addEventListener('change', calc); }
    var sC = HH.chart('chart-sa', {
      type: 'bar',
      data: { labels: ['2023 bill', 'Shock, no action', 'Shock + displacement'], datasets: [{ label: 'Bill at 2023 prices', data: [0, 0, 0], backgroundColor: XS }, { label: 'Extra cost of the shock', data: [0, 0, 0], backgroundColor: EK }] },
      options: { animation: false, indexAxis: 'y', layout: { padding: { right: 70 } }, plugins: { legend: { position: 'bottom' }, tooltip: { callbacks: { label: function (c) { return c.dataset.label + ': ' + fmt(c.raw, 2) + '% of GDP'; } } } }, scales: { x: Object.assign(axis({ title: 'fuel import bill, % of GDP' }), { stacked: true, min: 0 }), y: Object.assign(axis({ grid: false }), { stacked: true, ticks: Object.assign({ autoSkip: false }, tick) }) } },
      plugins: [{ id: 'tot', afterDatasetsDraw: function (ch) { var ctx = ch.ctx; ctx.save(); ctx.fillStyle = INK; ctx.font = '600 11px ' + tok('--mono'); ctx.textBaseline = 'middle'; var m1 = ch.getDatasetMeta(1); m1.data.forEach(function (bar, i) { var t = ch.data.datasets[0].data[i] + ch.data.datasets[1].data[i]; ctx.fillText(fmt(t, 1) + '%', Math.max(bar.x, ch.getDatasetMeta(0).data[i].x) + 5, bar.y); }); ctx.restore(); } }],
    });
    function gv(id) { var el = document.getElementById(id); return el ? +el.value / 100 : 0; }
